  "formula_ids":["hh10-duongtron-phuongtrinh"],
  "intro":"Bài này dùng công thức dạng $(x-a)^2+(y-b)^2=R^2$ của đường tròn để tìm tâm và bán kính.",
  "steps":[
    {
      "title":"Nhóm các hạng tử",
      "detail":"Đưa các hạng tử $x$ và $y$ sang một phía, hằng số sang phía còn lại.",
      "expression":"x^2 - 4x + y^2 + 6y = 12"
    },
    {
      "title":"Hoàn thành bình phương",
      "detail":"Thêm và trừ các bình phương hoàn chỉnh để viết dưới dạng bình phương hoàn chỉnh.",
      "expression":"(x - 2)^2 + (y + 3)^2 = 25"
    },
    {
      "title":"Áp dụng công thức đường tròn",
      "detail":"So sánh với công thức $(x-a)^2+(y-b)^2=R^2$, suy ra các tham số $a,b,R$.",
      "expression":"a = 2,\\; b = -3,\\; R = 5 \\Rightarrow (a,b,R) = ?"
    },
    {
      "title":"Kết luận",
      "detail":"Ghi nhận tâm và bán kính của đường tròn.",
      "expression":"Tâm = (a; b) = ?,\\; R = ?"
    }
  ],
  "reminder":"Bạn tự tính các ô ? rồi ghi đáp án nhé!"
}

